syntax:
SELECT …
FROM таблица
WHERE столбец IN (SELECT столбец FROM другая WHERE …);

SELECT …
FROM таблица
WHERE столбец = (SELECT столбец FROM другая WHERE ключ = …);

SELECT …
FROM таблица t
WHERE … (SELECT … FROM другая x WHERE x.ключ = t.ключ);

SELECT …
FROM таблица t
WHERE NOT EXISTS (
  SELECT 1 FROM другая x WHERE x.ключ = t.ключ
);
